import{_ as t,c as i,o as n,ae as a}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"COMBATING UNFAIR PRACTICES IN THE LIVE ENTERTAINMENT MARKET","description":"","frontmatter":{"title":"COMBATING UNFAIR PRACTICES IN THE LIVE ENTERTAINMENT MARKET","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/combating-unfair-practices-in-the-live-entertainment-market/","publishDate":"2025-03-31T19:43:28-04:00"},"headers":[],"relativePath":"executive-orders/2025-03-31-combating-unfair-practices-in-the-live-entertainment-market.md","filePath":"executive-orders/2025-03-31-combating-unfair-practices-in-the-live-entertainment-market.md"}'),r={name:"executive-orders/2025-03-31-combating-unfair-practices-in-the-live-entertainment-market.md"};function s(o,e,l,c,m,d){return n(),i("div",null,e[0]||(e[0]=[a('<h1 id="combating-unfair-practices-in-the-live-entertainment-market" tabindex="-1">COMBATING UNFAIR PRACTICES IN THE LIVE ENTERTAINMENT MARKET <a class="header-anchor" href="#combating-unfair-practices-in-the-live-entertainment-market" aria-label="Permalink to &quot;COMBATING UNFAIR PRACTICES IN THE LIVE ENTERTAINMENT MARKET&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/combating-unfair-practices-in-the-live-entertainment-market/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/combating-unfair-practices-in-the-live-entertainment-market/</a></p><p>Published: Monday, March 31, 2025</p><ul><li>The live concert and entertainment industry in America is facing issues due to middlemen, such as ticket scalpers, who charge excessive fees and manipulate the ticket purchasing process.</li><li>Fans are often forced to pay exorbitant prices (up to 70 times face value) to attend events, with profits going to scalpers instead of artists.</li><li>The Administration aims to make the arts and entertainment more accessible and is focused on eradicating exploitative practices in the ticketing industry.</li></ul><p><strong>Action Directives:</strong></p><ul><li>The Attorney General and Federal Trade Commission (FTC) are tasked with enforcing competition laws in the concert and entertainment sectors.</li><li>The FTC will rigorously enforce the Better Online Ticket Sales Act and collaborate with State Attorneys General for effective enforcement.</li><li>Steps will be taken to ensure price transparency during the ticket purchasing process.</li><li>The FTC will assess and address unfair practices in the secondary ticketing market.</li><li>The Secretary of the Treasury and Attorney General will ensure scalpers comply with tax laws and other regulations.</li></ul><p><strong>Reporting Requirements:</strong></p><ul><li>A report outlining implementation actions and potential regulatory or legislative recommendations is to be submitted within 180 days by the Secretary of the Treasury, Attorney General, and FTC Chairman.</li></ul><p><strong>Additional Provisions:</strong></p><ul><li>The order does not affect existing authority or functions of agencies involved.</li><li>Implementation is contingent upon legal compliance and available funding.</li><li>The order does not create any legal rights enforceable by any party against the U.S. government.</li></ul>',10)]))}const u=t(r,[["render",s]]);export{h as __pageData,u as default};
